    indices=[i for i,j in enumerate(m['jobs']) if j['mesh']==[48,24]];per_gen=[g[i]['monitor']['wall_seconds']/v[i]['states'] for i in indices];per_replay=[replay_monitors[i]['wall_seconds']/v[i]['states'] for i in indices];storage=[g[i]['result']['native_bytes']/v[i]['states'] for i in indices];rows=[]
